    AND status = #{status}
    AND node_group_id = #{groupId}

        AND (node_name ILIKE '%' || #{keyword} || '%' OR agent_id ILIKE '%' || #{keyword} || '%'
             OR COALESCE(ip_address,'') ILIKE '%' || #{keyword} || '%')


ORDER BY created_at DESC
LIMIT #{size} OFFSET #{offset}

SELECT COUNT(*) FROM compute_node

    AND status = #{status}
    AND node_group_id = #{groupId}

        AND (node_name ILIKE '%' || #{keyword} || '%' OR agent_id ILIKE '%' || #{keyword} || '%'
             OR COALESCE(ip_address,'') ILIKE '%' || #{keyword} || '%')

