UPDATE compute_node
node_group_id = #{nodeGroupId}, node_name = #{nodeName}, ip_address = #{ipAddress}, status = #{status}, agent_version = #{agentVersion}, os_info = #{osInfo}, cpu_info = #{cpuInfo}::jsonb, gpu_info = #{gpuInfo}::jsonb, total_memory = #{totalMemory}, total_disk = #{totalDisk}, last_heartbeat_at = #{lastHeartbeatAt}, updated_at = NOW()
